// Recorded autonomous-scenario traces (#114).
// Generated by apps/scenarios runner; MOCK label = fake Nemotron
// provider, no live model calls. Every claim must cite evidence ids.

export interface TraceStep {
  step: number
  evidence_id: string
  detail: string
}

export interface TraceClaim {
  text: string
  evidence_ids: string[]
}

export interface ScenarioTrace {
  schema: 'scenario-trace/1'
  scenario: string
  title: string
  label: 'MOCK' | 'LIVE'
  provenance: string
  ok: boolean
  duration_s: number
  agent_summary: string
  uncertainty: string
  steps: TraceStep[]
  claims: TraceClaim[]
  generated_at: number
}

import preventionTrace from './recorded/prevention-trace.json'
import interceptionTrace from './recorded/interception-trace.json'
import mitigationTrace from './recorded/mitigation-trace.json'

export const RECORDED_TRACES: Record<string, ScenarioTrace> = {
  prevention: preventionTrace as ScenarioTrace,
  interception: interceptionTrace as ScenarioTrace,
  mitigation: mitigationTrace as ScenarioTrace,
}

/** Validate trace completeness: every claim cites evidence produced by
 * a step; uncertainty + summary always present. Throws on violation. */
export function assertTraceComplete(t: ScenarioTrace): void {
  if (t.schema !== 'scenario-trace/1') throw new Error('bad schema')
  if (t.label !== 'MOCK' && t.label !== 'LIVE')
    throw new Error('missing MOCK/LIVE label')
  if (!t.agent_summary || !t.uncertainty)
    throw new Error('missing summary or uncertainty')
  const stepIds = new Set(t.steps.map((s) => s.evidence_id))
  for (const c of t.claims) {
    if (!c.evidence_ids.length) throw new Error('claim without evidence')
    for (const id of c.evidence_ids)
      if (id !== 'ev-none' && !stepIds.has(id))
        throw new Error(`claim cites unknown evidence ${id}`)
  }
}
